import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Container, Table, Button, Form, Modal, Spinner } from 'react-bootstrap';

const AdminDashboard = () => {
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editMode, setEditMode] = useState(false);
  const [currentEventId, setCurrentEventId] = useState(null);
  const [newEvent, setNewEvent] = useState({ title: '', description: '', date: '', image: null });

  const fetchEvents = async () => {
    try {
      const response = await axios.get('/api/events/admin-events', {
        headers: { Authorization: `Bearer ${localStorage.getItem('authToken')}` },
      });
      setEvents(response.data);
      setLoading(false);
    } catch (error) {
      console.error('Error fetching events:', error);
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchEvents();
  }, []);

  const handleShowModal = (event = null) => {
    if (event) {
      setEditMode(true);
      setCurrentEventId(event._id);
      setNewEvent({ title: event.title, description: event.description, date: event.date, image: event.image });
    } else {
      setEditMode(false);
      setCurrentEventId(null);
      setNewEvent({ title: '', description: '', date: '', image: null });
    }
    setShowModal(true);
  };

  const handleCloseModal = () => setShowModal(false);

  const handleChange = (e) => {
    const { name, value } = e.target;
    if (name === 'image') {
      setNewEvent((prevEvent) => ({ ...prevEvent, image: e.target.files[0] }));
    } else {
      setNewEvent((prevEvent) => ({ ...prevEvent, [name]: value }));
    }
  };
  
  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const formData = new FormData();
      formData.append('title', newEvent.title);
      formData.append('description', newEvent.description);
      formData.append('date', newEvent.date);
      formData.append('image', newEvent.image);
  
      if (editMode) {
        await axios.put(`/api/events/${currentEventId}`, formData, {
          headers: { Authorization: `Bearer ${localStorage.getItem('authToken')}` },
        });
      } else {
        await axios.post('/api/events', formData, {
          headers: { Authorization: `Bearer ${localStorage.getItem('authToken')}` },
        });
      }
  
      fetchEvents();  // Fetch updated list
      setShowModal(false);
      setNewEvent({ title: '', description: '', date: '', image: null });
    } catch (error) {
      console.error('Error creating/updating event:', error);
    }
  };
  
  const handleDelete = async (eventId) => {
    try {
      await axios.delete(`/api/events/${eventId}`, {
        headers: { Authorization: `Bearer ${localStorage.getItem('authToken')}` },
      });
      fetchEvents();
    } catch (error) {
      console.error('Error deleting event:', error);
    }
  };

  return (
    <Container className="admin-dashboard-container mt-5">
      <h2 className="text-center mb-4">Admin Dashboard</h2>
      {loading ? (
        <Spinner animation="border" role="status">
          <span className="visually-hidden">Loading...</span>
        </Spinner>
      ) : (
        <Table striped bordered hover>
          <thead>
            <tr>
              <th>Title</th>
              <th>Description</th>
              <th>Date</th>
              <th>Image</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {events.map((event) => (
              <tr key={event._id}>
                <td>{event.title}</td>
                <td>{event.description}</td>
                <td>{new Date(event.date).toLocaleDateString()}</td>
                <td>
                  <img 
                    src={event.image} 
                    alt={event.title} 
                    width="100" 
                    height="100" 
                    style={{ cursor: 'pointer' }}
                    onClick={() => handleShowModal()}
                  />
                </td>
                <td>
                  <Button variant="warning" onClick={() => handleShowModal(event)} className="me-2">
                    Edit
                  </Button>
                  <Button variant="danger" onClick={() => handleDelete(event._id)}>
                    Delete
                  </Button>
                </td>
              </tr>
            ))}
          </tbody>
        </Table>
      )}
      <Button variant="primary" onClick={() => handleShowModal()}>
        Create New Event
      </Button>
    </Container>
  );
};

export default AdminDashboard;
